#include "game.hpp"
#include <algorithm>
#include <cctype>
#include <iostream>
#include <string>
#ifdef _WIN32
#include <conio.h>
#endif
namespace echodrive {
Game::Game():settings_(loadSettings("echodrive.cfg")),voice_(settings_.language){audio_.setListener({0,0,0},0);route_.load(settings_.street);}
void Game::menu()const{std::cout<<"\n=== EchoDrive 0.6 | Ahmed Samy Studio ===\n[ARROWS] up/down=سرعة وفرامل left/right=توجيه | [F1-F12] وظائف\n[z/e] تقدم [x] فرامل [c/v] يسار/يمين [b/i] أسرع [n/o] أبطأ\n[a] آلي [m] يدوي [s/u] حالة [d/y] خريطة [f] تحكم [g] بوق [h] محرك\n[j/w] طقس [k/t] مرور [l] الشوارع [p] إيقاف [r] إعادة [q] خروج\n[Insert] محطات [Tab] سيارة جديدة [CapsLock] محرك [Enter] حالة [Esc] إيقاف\n> ";}
std::string Game::readInput()const{
#ifdef _WIN32
 int c=_getch();if(c==0||c==224){int k=_getch();if(k==72)return "up";if(k==80)return "down";if(k==75)return "left";if(k==77)return "right";if(k>=59&&k<=68)return "f"+std::to_string(k-58);if(k==133)return "f11";if(k==134)return "f12";if(k==82)return "insert";if(k==83)return "delete";return "";}if(c==27)return "esc";if(c==9)return "tab";if(c==20)return "capslock";if(c==13)return "enter";return std::string(1,(char)std::tolower(c));
#else
 std::string x;std::getline(std::cin,x);for(auto&c:x)c=(char)std::tolower((unsigned char)c);return x;
#endif
}
void Game::selectStreet(){std::cout<<"اختر شارعًا من 1 إلى 15: ";int n=1;std::cin>>n;std::cin.ignore(10000,'\n');if(n<1||n>15)n=1;settings_.street=n;route_.load(n);const auto&x=allStreets()[n-1];auto assets=assetsForStreet(n);runtime_.setListener({0,0,0},0);runtime_.playLoop(assets.ambience,{0,0,8},0.45f);traffic_.reset(n);voice_.announce("بدأت "+x.ar+" من دولة "+x.country+". المسافة "+std::to_string((int)route_.state().lengthM)+" متر","Starting "+x.en+" in "+x.country+". Route length "+std::to_string((int)route_.state().lengthM)+" meters");}
void Game::selectVehicle(){std::cout<<"اختر سيارة من 1 إلى 25: ";int n=1;std::cin>>n;std::cin.ignore(10000,'\n');if(n<1||n>25)n=1;vehicle_=n;auto assets=assetsForStreet(settings_.street);runtime_.playLoop(assets.engine,{0,0,1},0.70f);const auto&x=allVehicles()[n-1];voice_.announce("اخترت "+x.ar+"، السرعة القصوى "+std::to_string(x.topSpeed),"Selected "+x.en+", top speed "+std::to_string(x.topSpeed));}
Command Game::parse(const std::string&r)const{if(r=="1"||r=="up"||r=="forward"||r=="z"||r=="e"||r=="تقدم")return Command::Forward;if(r=="2"||r=="down"||r=="stop"||r=="x"||r=="توقف"||r=="فرامل")return Command::Brake;if(r=="3"||r=="right"||r=="v"||r=="يمين")return Command::Right;if(r=="4"||r=="left"||r=="c"||r=="يسار")return Command::Left;if(r=="5"||r=="+"||r=="b"||r=="i"||r=="أسرع")return Command::Faster;if(r=="6"||r=="-"||r=="n"||r=="o"||r=="أبطئ")return Command::Slower;if(r=="a"||r=="auto"||r=="قيادة آلية")return Command::Auto;if(r=="m"||r=="manual"||r=="قيادة يدوية")return Command::Manual;if(r=="s"||r=="u"||r=="status"||r=="حالة"||r=="enter"||r=="f1")return Command::Repeat;if(r=="r"||r=="reset"||r=="إعادة"||r=="f11")return Command::Reset;if(r=="l"||r=="streets")return Command::ListStreets;if(r=="vehicles"||r=="listvehicles")return Command::ListVehicles;if(r=="w"||r=="j"||r=="weather"||r=="طقس"||r=="f3")return Command::WeatherCycle;if(r=="t"||r=="k"||r=="traffic"||r=="مرور"||r=="f4")return Command::Traffic;if(r=="d"||r=="y"||r=="map"||r=="خريطة"||r=="f2")return Command::Map;if(r=="f"||r=="controls"||r=="تحكم"||r=="f9")return Command::Controls;if(r=="g"||r=="horn")return Command::Horn;if(r=="p"||r=="pause"||r=="esc"||r=="f10")return Command::Pause;if(r=="h"||r=="engine"||r=="capslock")return Command::Engine;if(r=="insert"||r=="f5")return Command::Stations;if(r=="tab"||r=="f7")return Command::NewVehicle;if(r=="f6"||r=="customize")return Command::Customize;if(r=="f8"||r=="language")return Command::Language;if(r=="f12"||r=="region"||r=="f0")return Command::RegionMap;if(r=="delete")return Command::NewVehicle;if(r=="q"||r=="quit"||r=="خروج")return Command::Quit;return Command::Unknown;}
void Game::status()const{const auto&rs=route_.state();voice_.announce("السرعة "+std::to_string((int)speed_)+"، قطعت "+std::to_string((int)rs.progressM)+" متر، متبقي "+std::to_string((int)(rs.lengthM-rs.progressM))+" متر، "+vehicleSystem_.status(true)+"، "+vehicleSystem_.customize(true),"Speed "+std::to_string((int)speed_)+", travelled "+std::to_string((int)rs.progressM)+" meters, remaining "+std::to_string((int)(rs.lengthM-rs.progressM))+" meters, "+vehicleSystem_.status(false)+", "+vehicleSystem_.customize(false));}
void Game::showControls()const{std::cout<<"\n--- Controls ---\nArrows: up/down/left/right\nF1 status | F2 map | F3 weather | F4 traffic | F5 stations | F6 customize | F7 new car | F8 language | F9 help | F10 pause | F11 reset | F12 Egypt regions\nEsc pause | Insert stations | Enter status | CapsLock engine | Tab next car | Delete next car\nZ/E forward | X brake | C/V steer | B/I faster | N/O slower | A auto | M manual | G horn | Q quit\nMouse buttons are reserved for the upcoming graphical desktop front-end.\n";voice_.announce("تم عرض اختصارات F1 إلى F12 ومفاتيح النظام","F1 to F12 and system key shortcuts are shown");}
void Game::listContent()const{std::cout<<"\n--- 15 Streets ---\n";for(const auto&s:allStreets())std::cout<<s.id<<". "<<s.en<<" — "<<s.country<<"\n";std::cout<<"\n--- 25 Vehicles ---\n";for(const auto&v:allVehicles())std::cout<<v.id<<". "<<v.en<<" ["<<v.category<<"] max "<<v.topSpeed<<" km/h\n";}
void Game::handle(Command c){if(paused_&&c!=Command::Pause&&c!=Command::Quit){voice_.announce("اللعبة متوقفة، اضغط Escape أو F10","Game paused, press Escape or F10");return;}switch(c){case Command::Forward:speed_=std::min((double)allVehicles()[vehicle_-1].topSpeed,speed_+8);route_.advance(speed_);traffic_.tick(speed_,settings_.automaticDriving);break;case Command::Brake:speed_=std::max(0.0,speed_-20);route_.advance(speed_*.15);traffic_.tick(speed_,settings_.automaticDriving);break;case Command::Right:heading_=1;audio_.setListener({0,0,0},0.25);break;case Command::Left:heading_=-1;audio_.setListener({0,0,0},-0.25);break;case Command::Faster:speed_=std::min((double)allVehicles()[vehicle_-1].topSpeed,speed_+15);route_.advance(speed_);break;case Command::Slower:speed_=std::max(0.0,speed_-15);break;case Command::Auto:settings_.automaticDriving=true;break;case Command::Manual:settings_.automaticDriving=false;break;case Command::Reset:speed_=0;heading_=0;route_.reset();traffic_.reset(settings_.street);weather_.set(Weather::Clear);break;case Command::Repeat:status();break;case Command::ListStreets:case Command::ListVehicles:listContent();break;case Command::WeatherCycle:weather_.cycle();runtime_.playLoop(weather_.ambiencePath(),{0,0,5},0.38f);voice_.announce("الطقس الآن "+weather_.name(true)+". "+weather_.advisory(true),"Weather is now "+weather_.name(false)+". "+weather_.advisory(false));break;case Command::Traffic:traffic_.tick(speed_,settings_.automaticDriving);voice_.announce(traffic_.nearestAlert(true),traffic_.nearestAlert(false));break;case Command::Map:voice_.announce(route_.render(true),route_.render(false));std::cout<<route_.render(true)<<"\n";break;case Command::Controls:showControls();break;case Command::Horn:runtime_.playOneShot("assets/audio/vehicles/Car_Horn.ogg",{1,0,3},0.8f);voice_.announce("بوق","Horn");break;case Command::Pause:paused_=!paused_;voice_.announce(paused_?"تم إيقاف اللعبة":"تم استئناف اللعبة",paused_?"Game paused":"Game resumed");break;case Command::Engine:engineOn_=!engineOn_;if(!engineOn_)speed_=0;voice_.announce(engineOn_?"تم تشغيل المحرك":"تم إيقاف المحرك",engineOn_?"Engine on":"Engine off");break;case Command::Stations:voice_.announce(vehicleSystem_.stations(true)+". "+vehicleSystem_.status(true),vehicleSystem_.stations(false)+". "+vehicleSystem_.status(false));vehicleSystem_.refuel();vehicleSystem_.changeOil();vehicleSystem_.charge();break;case Command::Customize:{static const char* colors[]={"blue","red","green","black","white","yellow"};static int i=0;vehicleSystem_.setColor(colors[++i%6]);vehicleSystem_.upgradeEngine(i%2?"sport":"standard");vehicleSystem_.upgradeBrakes(i%2?"abs-sport":"standard");voice_.announce(vehicleSystem_.customize(true),vehicleSystem_.customize(false));break;}case Command::Language:{int n=((int)voice_.language()+1)%6;settings_.language=(Language)n;voice_.setLanguage(settings_.language);voice_.announce6("تم اختيار العربية","English selected","Français sélectionné","Español seleccionado","Выбран русский язык","日本語を選択しました");break;}case Command::RegionMap:region_=region_%27+1;voice_.announce(regionMapSummary(region_,true),regionMapSummary(region_,false));break;case Command::NewVehicle:vehicle_=vehicle_%25+1;selectVehicle();break;case Command::Quit:saveSettings(settings_,"echodrive.cfg");voice_.announce("إلى اللقاء","Goodbye");break;case Command::Unknown:voice_.announce("لم أفهم الأمر","Command not understood");}}
void Game::run(){voice_.announce("مرحبًا بك في EchoDrive. اللغات والمحطات والتخصيص ومحافظات مصر مفعلة.","Welcome to EchoDrive. Languages, stations, customization and Egypt regions are enabled.");selectStreet();selectVehicle();for(;;){menu();std::string x=readInput();Command c=parse(x);handle(c);if(c==Command::Quit)break;}}
}
